SELECT count() AS rows, sum(f.amount) AS total, uniqExact(c.region) AS regions
FROM join_lab.facts AS f
INNER JOIN join_lab.customers AS c ON f.customer_id = c.id;

SELECT count() AS n
FROM (SELECT amount FROM join_lab.facts WHERE id < 100000) AS f
INNER JOIN join_lab.bands AS b ON abs(f.amount - b.lo) < 10;

SELECT count() AS n, countIf(b.hi = 0) AS unmatched
FROM (SELECT amount FROM join_lab.facts WHERE id < 100000) AS f
LEFT JOIN join_lab.bands AS b ON abs(f.amount - b.lo) < 10;

SELECT count() AS n, sum(f.amount) AS total
FROM join_lab.facts AS f
INNER JOIN join_lab.customers AS c ON f.customer_id = c.id AND f.amount > c.credit_limit;

SELECT count() AS n, countIf(c.credit_limit = 0) AS no_match_or_zero
FROM join_lab.facts AS f
LEFT JOIN join_lab.customers AS c ON f.customer_id = c.id AND f.amount > c.credit_limit;

SELECT count() AS n
FROM join_lab.customers AS c
WHERE NOT EXISTS (SELECT 1 FROM join_lab.facts AS f WHERE f.customer_id = c.id AND f.amount > 9990);

SELECT count() AS n, sum(f.amount) AS total
FROM join_lab.facts AS f
INNER JOIN (SELECT id FROM join_lab.customers WHERE id % 1000 = 0) AS c ON f.customer_id = c.id;

SELECT count() AS n, sum(cityHash64(c.comment)) AS h
FROM join_lab.facts AS f
INNER JOIN join_lab.customers_big AS c ON f.customer_id = c.id;

SELECT count() AS n, sum(p.price) AS total
FROM (SELECT customer_id, ts FROM join_lab.facts WHERE id < 1000000 AND customer_id < 2000) AS f
ASOF LEFT JOIN join_lab.prices AS p ON f.customer_id = p.customer_id AND f.ts >= p.ts;

SELECT count() AS n, sum(a.x + b.y) AS total
FROM (SELECT number AS x FROM numbers(5)) AS a
PASTE JOIN (SELECT number * 10 AS y FROM numbers(5)) AS b;

SELECT count() AS n
FROM (SELECT number AS id, number * 2 AS a FROM numbers(5)) AS l
NATURAL JOIN (SELECT number AS id, number * 3 AS b FROM numbers(5)) AS r;

SELECT count() AS n
FROM (SELECT number AS id FROM numbers(5)) AS l
INNER JOIN (SELECT number AS id FROM numbers(3)) AS r USING (id);

SELECT count() AS rows, sum(f.amount) AS total, uniqExact(c.region) AS regions
FROM join_lab.facts_big AS f
INNER JOIN join_lab.customers_big AS c ON f.customer_id = c.id;

SELECT count() AS rows, sum(f.amount) AS total, uniqExact(c.region) AS regions
FROM join_lab.customers_big AS c
INNER JOIN join_lab.facts_big AS f ON f.customer_id = c.id;

SELECT groupUniqArray(compression_codec) AS column_codecs, count() AS columns
FROM system.columns
WHERE database = 'join_lab' AND table IN ('facts_big', 'customers_big', 'contacts_big');

SELECT groupUniqArray(default_compression_codec) AS part_default_codecs, count() AS parts, max(bytes_on_disk) AS max_part_bytes
FROM system.parts
WHERE database = 'join_lab' AND table IN ('facts_big', 'customers_big', 'contacts_big') AND active;

SELECT count() AS n
FROM join_lab.regions AS r, LATERAL (SELECT c.id FROM join_lab.customers AS c WHERE c.region = r.id LIMIT 2) AS l
SETTINGS allow_experimental_lateral_join = 1;
